import 'package:flutter/material.dart';
import 'package:url_launcher/url_launcher.dart';

const bg = Color(0xFFF7FAF7);
const surface = Colors.white;
const surface2 = Color(0xFFF0F5F0);
const green = Color(0xFF2E9E4F);
const greenDark = Color(0xFF1E7A3D);
const gold = Color(0xFFD6AD45);
const text = Color(0xFF172019);
const muted = Color(0xFF667066);
const warning = Color(0xFFD58A00);
const danger = Color(0xFFC83C3C);
const border = Color(0xFFDCE5DC);
const site = 'https://farmplugaisxd.vercel.app';

void main() => runApp(const FarmPlug());

class FarmPlug extends StatelessWidget {
  const FarmPlug({super.key});
  @override
  Widget build(BuildContext context) => MaterialApp(
    debugShowCheckedModeBanner: false,
    title: 'FarmPlug AI',
    theme: ThemeData(
      useMaterial3: true,
      brightness: Brightness.light,
      scaffoldBackgroundColor: bg,
      colorScheme: ColorScheme.fromSeed(seedColor: green, brightness: Brightness.light),
      cardTheme: const CardThemeData(color: surface, elevation: 0, margin: EdgeInsets.zero),
      inputDecorationTheme: const InputDecorationTheme(
        filled: true, fillColor: surface,
        border: OutlineInputBorder(borderRadius: BorderRadius.all(Radius.circular(14)), borderSide: BorderSide(color: border)),
        enabledBorder: OutlineInputBorder(borderRadius: BorderRadius.all(Radius.circular(14)), borderSide: BorderSide(color: border)),
        focusedBorder: OutlineInputBorder(borderRadius: BorderRadius.all(Radius.circular(14)), borderSide: BorderSide(color: green, width: 1.5)),
      ),
    ),
    home: const Splash(),
  );
}

Future<void> openSite(BuildContext context, String path) async {
  final ok = await launchUrl(Uri.parse('$site$path'), mode: LaunchMode.externalApplication);
  if (!ok && context.mounted) ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Unable to open FarmPlug')));
}

void push(BuildContext c, Widget page) => Navigator.of(c).push(MaterialPageRoute(builder: (_) => page));
void root(BuildContext c, Widget page) => Navigator.of(c).pushAndRemoveUntil(MaterialPageRoute(builder: (_) => page), (_) => false);

class Splash extends StatefulWidget { const Splash({super.key}); @override State<Splash> createState() => _SplashState(); }
class _SplashState extends State<Splash> {
  @override void initState() { super.initState(); Future.delayed(const Duration(milliseconds: 800), () { if (mounted) Navigator.pushReplacement(context, MaterialPageRoute(builder: (_) => const Welcome())); }); }
  @override Widget build(BuildContext c) => const Scaffold(body: Center(child: Column(mainAxisSize: MainAxisSize.min, children: [Icon(Icons.eco_rounded, color: green, size: 70), SizedBox(height: 14), Text('FarmPlug AI', style: TextStyle(color: text, fontSize: 30, fontWeight: FontWeight.w800)), SizedBox(height: 8), Text('Smart farming. Better decisions. Greater yields.', style: TextStyle(color: muted)), SizedBox(height: 22), SizedBox(width: 24, height: 24, child: CircularProgressIndicator(color: green, strokeWidth: 2))])));
}

class Frame extends StatelessWidget {
  final String title, subtitle; final List<Widget> children;
  const Frame({super.key, required this.title, required this.subtitle, required this.children});
  @override Widget build(BuildContext c) => Scaffold(
    appBar: AppBar(title: Text(title, style: const TextStyle(fontWeight: FontWeight.w800)), backgroundColor: bg, foregroundColor: text, elevation: 0, leading: Navigator.of(c).canPop() ? const BackButton() : null),
    body: SafeArea(child: GestureDetector(onTap: () => FocusScope.of(c).unfocus(), child: ListView(keyboardDismissBehavior: ScrollViewKeyboardDismissBehavior.onDrag, padding: const EdgeInsets.fromLTRB(20, 12, 20, 30), children: [Text(subtitle, style: const TextStyle(color: muted, height: 1.4)), const SizedBox(height: 18), ...children.map((x) => Padding(padding: const EdgeInsets.only(bottom: 14), child: x))]))),
  );
}

Widget field(String label, IconData icon, {bool obscure = false, TextEditingController? controller, TextInputType? keyboardType, String? Function(String?)? validator}) => TextFormField(
  controller: controller, obscureText: obscure, keyboardType: keyboardType, validator: validator, autocorrect: !obscure,
  decoration: InputDecoration(labelText: label, prefixIcon: Icon(icon), contentPadding: const EdgeInsets.symmetric(horizontal: 14, vertical: 15)),
);

Widget button(String label, VoidCallback onTap) => SizedBox(width: double.infinity, height: 52, child: FilledButton(onPressed: onTap, style: FilledButton.styleFrom(backgroundColor: green, foregroundColor: Colors.white, shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14))), child: Text(label, style: const TextStyle(fontWeight: FontWeight.w700))));
Widget outline(String label, VoidCallback onTap) => SizedBox(width: double.infinity, height: 50, child: OutlinedButton(onPressed: onTap, style: OutlinedButton.styleFrom(foregroundColor: green, side: const BorderSide(color: green), shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(14))), child: Text(label, style: const TextStyle(fontWeight: FontWeight.w700))));
Widget section(String title) => Padding(padding: const EdgeInsets.only(top: 4, bottom: 2), child: Align(alignment: Alignment.centerLeft, child: Text(title, style: const TextStyle(color: text, fontSize: 18, fontWeight: FontWeight.w800))));

