class OrderTile extends StatelessWidget{final String id,item,status,date;final VoidCallback onTap;const OrderTile({super.key,required this.id,required this.item,required this.status,required this.date,required this.onTap});@override Widget build(BuildContext c)=>Card(child:ListTile(onTap:onTap,contentPadding:const EdgeInsets.all(12),leading:const CircleAvatar(backgroundColor:surface2,child:Icon(Icons.receipt_long_outlined,color:green)),title:Text(id,style:const TextStyle(fontWeight:FontWeight.w800,color:text)),subtitle:Text('$item · $date',style:const TextStyle(color:muted)),trailing:Text(status,style:TextStyle(color:status=='Pending'?warning:green,fontWeight:FontWeight.w700))));}
